import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()

    n = int(input[0])
    cards = []
    index = 1
    for _ in range(2 * n):
        a = int(input[index])
        b = int(input[index + 1])
        cards.append((a, b))
        index += 2

    def is_balanced(sequence):
        stack = []
        for num in sequence:
            if num > 0:
                stack.append(num)
            else:
                if not stack or stack[-1] != -num:
                    return False
                stack.pop()
        return len(stack) == 0

    def dfs(node, visited, match, graph):
        if visited[node]:
            return False
        visited[node] = True
        for neighbor in graph[node]:
            if match[neighbor] == -1 or dfs(match[neighbor], visited, match, graph):
                match[neighbor] = node
                return True
        return False

    def bipartite_matching(graph, left_size):
        match = [-1] * (2 * n + 1)
        result = 0
        for u in range(1, left_size + 1):
            visited = [False] * (2 * n + 1)
            if dfs(u, visited, match, graph):
                result += 1
        return result, match

    graph = defaultdict(list)
    for i, (a, b) in enumerate(cards):
        graph[a].append(b + n)
        graph[b].append(a + n)

    matching_size, match = bipartite_matching(graph, n)
    if matching_size != n:
        print("NO")
        return

    result = []
    used = [False] * (2 * n)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if match[j] == i:
                for k, (a, b) in enumerate(cards):
                    if (a == i and b == j - n) or (a == j - n and b == i):
                        if not used[k]:
                            result.append(cards[k])
                            used[k] = True
                            break

    front_sequence = [card[0] for card in result]
    back_sequence = [card[1] for card in result]

    if is_balanced(front_sequence) and is_balanced(back_sequence):
        print("YES")
        for card in result:
            print(card[0], card[1])
    else:
        print("NO")

if __name__ == "__main__":
    main()
